const tabKeys:Record<string,string>={'Overview':'overview','Conversation':'comments','Labels':'labels','Assignees':'assignees','Files changed':'files','Checks':'checks','Reviews':'reviews','Commits':'commits','Jobs':'jobs','Logs':'logs','Artifacts':'artifacts','Workflows':'workflows','Release notes':'overview','Assets':'assets','Items':'items','Fields':'fields','Answers':'answers','Alert':'overview','Locations':'locations','Members':'members','Teams':'teams','Repositories':'repositories','Files':'files','Comments':'comments','Ports':'ports','Branches':'branches','Collaborators':'collaborators'};
