interface Editor {action:string;title:string;destructive?:boolean;fields:Field[];values:Record<string,unknown>;review:boolean;keyOne:boolean;keyTwo:boolean;confirmation:number;reviewId?:string;expiresAt?:string;warnings?:string[];repository?:string;id?:string;target?:string}
interface Field {key:string;label:string;yue:string;kind?:'body'|'select'|'entity'|'file'|'directory'|'pairs'|'toggle'|'number';options?:string[];entity?:string;required?:boolean;hint?:string}
