 private copy(en:string,yue:string){return ui(this.settings,en,yue);}
 protected willUpdate(changed:Map<string,unknown>){if(changed.has('hostname')){this.nativeTask=undefined;this.cliTask=undefined;this.nativeArea='';this.editor=undefined;this.nativeDirty=false;}if(changed.has('repository')||changed.has('domain')||changed.has('authenticated')||changed.has('hostname')){this.listGeneration++;this.detailGeneration++;this.selected=undefined;this.detail={};this.detailRows=[];this.activeTab=this.viewTabs[0];this.state=this.definition.states?.[0]||'';this.query='';this.checked=new Set();this.rows=[];this.page={items:[],page:1,hasNext:false};void this.load();}}
